document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("work_date");if(!n)return;const o=e=>{if(e)try{const t=new URL(window.location.href),r=t.searchParams;r.set("work_date",e),r.delete("page"),t.search=r.toString(),window.location.href=t.toString()}catch{}};n.addEventListener("change",function(){o(this.value??null)}),n.addEventListener("keydown",function(e){e.key==="Enter"&&(e.preventDefault(),o(this.value??null))})});
